from taf.sw.dcap.rd.schemas.base import SchemaField, SchemaObject


class UploadResultInfoV1(SchemaObject):
    operation_status = SchemaField(name="operation_status")
    session_id = SchemaField(name="session_id")
    grid_ids = SchemaField(name="grid_ids", many=True)
    file_ids = SchemaField(name="file_ids", many=True)
    source_ids = SchemaField(name="source_ids", many=True)
    file_names = SchemaField(name="file_names", many=True)
    file_statuses = SchemaField(name="file_statuses", many=True)

    def __init__(self, operation_status=None, session_id=None, grid_ids=None, file_ids=None, source_ids=None,
                 file_names=None, file_statuses=None):
        self.operation_status = operation_status
        self.session_id = session_id
        self.grid_ids = grid_ids
        self.file_ids = file_ids
        self.source_ids = source_ids
        self.file_names = file_names
        self.file_statuses = file_statuses

        super(UploadResultInfoV1, self).__init__()
